using System;
using System.Collections;
using System.Collections.Generic;
using System.Data;
using BO;
using DataAccess;
using SimsObject;
using SystemService;

namespace InformationWeb.Utility
{
    /// <summary>
    /// Load dữ liệu dashboard sĩ số lớp qua stored procedure DASH_StudentClassSize_GetData.
    /// Gọi SP theo @ResultSet (1..6) vì Object layer chỉ hỗ trợ GetDataTable một result set.
    /// </summary>
    public class StudentClassSizeDashboardService
    {
        private const string SP_NAME = "DASH_StudentClassSize_GetData";

        public class FilterDefaults
        {
            public string YearID;
            public string Semester;
            public string Month;
        }

        public FilterDefaults GetDefaultFilters()
        {
            FilterDefaults objDefaults = new FilterDefaults();
            objDefaults.YearID = SYS_SettingService.GetStringValue("CurrentYearID");
            objDefaults.Semester = SYS_SettingService.GetStringValue("CurrentSemester");
            objDefaults.Month = DateTime.Now.ToString("yyyy-MM-01");
            return objDefaults;
        }

        public DataTable GetYears()
        {
            return new SIM_YearDAO().Search();
        }

        public DataTable GetSciences()
        {
            return new SIM_ScienceDAO().Search();
        }

        public DataTable GetCourses()
        {
            return new SIM_CourseDAO().Search("@IsActived", 1);
        }

        public DataTable GetClasses()
        {
            return new SIM_ClassDAO().Search("@ClassType", 0, "@IsActived", 1);
        }

        public Dictionary<string, DataTable> GetDashboardData(
            string scienceId,
            string courseId,
            string classId,
            int yearId,
            byte semester,
            DateTime month)
        {
            Dictionary<string, DataTable> dicResult = new Dictionary<string, DataTable>();
            SIM_Class objClass = new SIM_Class();
            object objMonth = month;

            dicResult["summary"] = CallResultSet(objClass, scienceId, courseId, classId, yearId, semester, objMonth, 1);
            dicResult["byClass"] = CallResultSet(objClass, scienceId, courseId, classId, yearId, semester, objMonth, 2);
            dicResult["genderByClass"] = CallResultSet(objClass, scienceId, courseId, classId, yearId, semester, objMonth, 3);
            dicResult["monthTrend"] = CallResultSet(objClass, scienceId, courseId, classId, yearId, semester, objMonth, 4);
            dicResult["byScience"] = CallResultSet(objClass, scienceId, courseId, classId, yearId, semester, objMonth, 5);
            dicResult["abnormal"] = CallResultSet(objClass, scienceId, courseId, classId, yearId, semester, objMonth, 6);

            return dicResult;
        }

        private DataTable CallResultSet(
            SIM_Class objClass,
            string scienceId,
            string courseId,
            string classId,
            int yearId,
            byte semester,
            object month,
            byte resultSet)
        {
            return objClass.GetDataTable(
                SP_NAME,
                "@ScienceID", NormalizeFilter(scienceId),
                "@CourseID", NormalizeFilter(courseId),
                "@ClassID", NormalizeFilter(classId),
                "@YearID", yearId,
                "@Semester", semester,
                "@Month", month,
                "@ResultSet", resultSet);
        }

        private object NormalizeFilter(string value)
        {
            if (value == null || value.Trim() == "" || value == "0" || value.ToLower() == "all")
                return DBNull.Value;
            return value.Trim();
        }

        public static List<Dictionary<string, object>> DataTableToList(DataTable dtb)
        {
            List<Dictionary<string, object>> lstRows = new List<Dictionary<string, object>>();
            if (dtb == null)
                return lstRows;

            int intCol;
            int intRow;
            for (intRow = 0; intRow < dtb.Rows.Count; intRow++)
            {
                Dictionary<string, object> dicRow = new Dictionary<string, object>();
                for (intCol = 0; intCol < dtb.Columns.Count; intCol++)
                {
                    object objValue = dtb.Rows[intRow][intCol];
                    if (objValue == DBNull.Value)
                        dicRow[dtb.Columns[intCol].ColumnName] = null;
                    else if (objValue is DateTime)
                        dicRow[dtb.Columns[intCol].ColumnName] = ((DateTime)objValue).ToString("yyyy-MM-dd");
                    else
                        dicRow[dtb.Columns[intCol].ColumnName] = objValue;
                }
                lstRows.Add(dicRow);
            }
            return lstRows;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Data;
using System.IO;
using System.Text;
using System.Web;
using System.Web.Script.Serialization;
using System.Web.SessionState;
using BO;
using InformationWeb.Utility;

namespace InformationWeb
{
    /// <summary>
    /// API JSON cho dashboard sĩ số lớp.
    /// POST action=filters | action=data
    /// </summary>
    public class StudentClassSizeDashboardApi : IHttpHandler, IReadOnlySessionState
    {
        private const string PERMISSION_VIEW = "frmWebStudentList_View";

        public void ProcessRequest(HttpContext context)
        {
            context.Response.ContentType = "application/json";
            context.Response.ContentEncoding = Encoding.UTF8;

            if (WebGlobal.User == null)
            {
                WriteJson(context, false, "Bạn chưa đăng nhập hệ thống.", null);
                return;
            }

            if (!WebGlobal.HasPermission(PERMISSION_VIEW))
            {
                WriteJson(context, false, "Bạn không có quyền xem dashboard sĩ số lớp.", null);
                return;
            }

            string strAction = GetRequestValue(context, "action");
            if (strAction == null || strAction == "")
                strAction = "data";

            try
            {
                StudentClassSizeDashboardService objService = new StudentClassSizeDashboardService();

                if (strAction.ToLower() == "filters")
                {
                    HandleFilters(context, objService);
                    return;
                }

                if (strAction.ToLower() == "data")
                {
                    HandleData(context, objService);
                    return;
                }

                WriteJson(context, false, "Action không hợp lệ.", null);
            }
            catch (Exception ex)
            {
                WriteJson(context, false, "Có lỗi xảy ra khi tải dữ liệu dashboard.", null);
            }
        }

        private void HandleFilters(HttpContext context, StudentClassSizeDashboardService objService)
        {
            StudentClassSizeDashboardService.FilterDefaults objDefaults = objService.GetDefaultFilters();
            Dictionary<string, object> dicData = new Dictionary<string, object>();

            dicData["years"] = BuildSelectList(objService.GetYears(), SIM_Year.C_YEARID, SIM_Year.C_YEARNAME);
            dicData["semesters"] = BuildSemesterList();
            dicData["sciences"] = BuildSelectList(objService.GetSciences(), SIM_Science.C_SCIENCEID, SIM_Science.C_SCIENCENAME, true);
            dicData["courses"] = BuildSelectList(objService.GetCourses(), SIM_Course.C_COURSEID, SIM_Course.C_COURSENAME, true);
            dicData["classes"] = BuildSelectList(objService.GetClasses(), SIM_Class.C_CLASSID, SIM_Class.C_CLASSNAME, true);
            dicData["defaults"] = objDefaults;
            dicData["months"] = BuildMonthList();

            WriteJson(context, true, "", dicData);
        }

        private void HandleData(HttpContext context, StudentClassSizeDashboardService objService)
        {
            string strYearId = GetRequestValue(context, "yearId");
            string strSemester = GetRequestValue(context, "semester");
            string strMonth = GetRequestValue(context, "month");
            string strScienceId = GetRequestValue(context, "scienceId");
            string strCourseId = GetRequestValue(context, "courseId");
            string strClassId = GetRequestValue(context, "classId");

            if (strYearId == null || strYearId == "" || strSemester == null || strSemester == "" || strSemester == "-1")
            {
                WriteJson(context, false, "Vui lòng chọn năm học và học kỳ.", null);
                return;
            }

            int intYearId = Convert.ToInt32(strYearId);
            byte bySemester = Convert.ToByte(strSemester);
            DateTime dtmMonth = ParseMonth(strMonth);

            Dictionary<string, DataTable> dicTables = objService.GetDashboardData(
                strScienceId,
                strCourseId,
                strClassId,
                intYearId,
                bySemester,
                dtmMonth);

            if (dicTables["summary"] == null)
            {
                WriteJson(context, false, "Không tải được dữ liệu từ hệ thống.", null);
                return;
            }

            Dictionary<string, object> dicData = new Dictionary<string, object>();
            dicData["summary"] = StudentClassSizeDashboardService.DataTableToList(dicTables["summary"]);
            dicData["byClass"] = StudentClassSizeDashboardService.DataTableToList(dicTables["byClass"]);
            dicData["genderByClass"] = StudentClassSizeDashboardService.DataTableToList(dicTables["genderByClass"]);
            dicData["monthTrend"] = StudentClassSizeDashboardService.DataTableToList(dicTables["monthTrend"]);
            dicData["byScience"] = StudentClassSizeDashboardService.DataTableToList(dicTables["byScience"]);
            dicData["abnormal"] = StudentClassSizeDashboardService.DataTableToList(dicTables["abnormal"]);
            dicData["updatedAt"] = DateTime.Now.ToString("dd/MM/yyyy HH:mm");

            WriteJson(context, true, "", dicData);
        }

        private DateTime ParseMonth(string strMonth)
        {
            if (strMonth == null || strMonth == "")
                return Convert.ToDateTime(DateTime.Now.ToString("yyyy-MM-01"));

            if (strMonth.Length == 7)
                return Convert.ToDateTime(strMonth + "-01");

            return Convert.ToDateTime(strMonth);
        }

        private List<Dictionary<string, string>> BuildSelectList(DataTable dtb, string valueField, string textField)
        {
            return BuildSelectList(dtb, valueField, textField, false);
        }

        private List<Dictionary<string, string>> BuildSelectList(DataTable dtb, string valueField, string textField, bool includeAll)
        {
            List<Dictionary<string, string>> lstItems = new List<Dictionary<string, string>>();
            if (includeAll)
            {
                Dictionary<string, string> dicAll = new Dictionary<string, string>();
                dicAll["value"] = "";
                dicAll["text"] = "Tất cả";
                lstItems.Add(dicAll);
            }

            if (dtb == null)
                return lstItems;

            int intRow;
            for (intRow = 0; intRow < dtb.Rows.Count; intRow++)
            {
                Dictionary<string, string> dicItem = new Dictionary<string, string>();
                dicItem["value"] = Convert.ToString(dtb.Rows[intRow][valueField]);
                dicItem["text"] = Convert.ToString(dtb.Rows[intRow][textField]);
                lstItems.Add(dicItem);
            }
            return lstItems;
        }

        private List<Dictionary<string, string>> BuildSemesterList()
        {
            List<Dictionary<string, string>> lstItems = new List<Dictionary<string, string>>();
            Dictionary<string, string> dicSem1 = new Dictionary<string, string>();
            dicSem1["value"] = "1";
            dicSem1["text"] = "Học kỳ I";
            lstItems.Add(dicSem1);

            Dictionary<string, string> dicSem2 = new Dictionary<string, string>();
            dicSem2["value"] = "2";
            dicSem2["text"] = "Học kỳ II";
            lstItems.Add(dicSem2);
            return lstItems;
        }

        private List<Dictionary<string, string>> BuildMonthList()
        {
            List<Dictionary<string, string>> lstItems = new List<Dictionary<string, string>>();
            int intMonth;
            for (intMonth = 1; intMonth <= 12; intMonth++)
            {
                Dictionary<string, string> dicItem = new Dictionary<string, string>();
                dicItem["value"] = String.Format("{0}-{1:00}", DateTime.Now.Year, intMonth);
                dicItem["text"] = String.Format("Tháng {0}", intMonth);
                lstItems.Add(dicItem);
            }
            return lstItems;
        }

        private string GetRequestValue(HttpContext context, string key)
        {
            if (context.Request[key] != null && context.Request[key] != "")
                return context.Request[key];

            string strBody = ReadRequestBody(context);
            if (strBody == null || strBody == "")
                return null;

            JavaScriptSerializer objSerializer = new JavaScriptSerializer();
            Dictionary<string, object> dicBody = objSerializer.Deserialize<Dictionary<string, object>>(strBody);
            if (dicBody == null || !dicBody.ContainsKey(key) || dicBody[key] == null)
                return null;

            return Convert.ToString(dicBody[key]);
        }

        private string ReadRequestBody(HttpContext context)
        {
            if (context.Request.InputStream == null)
                return null;

            context.Request.InputStream.Position = 0;
            StreamReader objReader = new StreamReader(context.Request.InputStream, Encoding.UTF8);
            return objReader.ReadToEnd();
        }

        private void WriteJson(HttpContext context, bool success, string message, object data)
        {
            Dictionary<string, object> dicResponse = new Dictionary<string, object>();
            dicResponse["success"] = success;
            dicResponse["message"] = message;
            dicResponse["data"] = data;

            JavaScriptSerializer objSerializer = new JavaScriptSerializer();
            objSerializer.MaxJsonLength = int.MaxValue;
            context.Response.Write(objSerializer.Serialize(dicResponse));
        }

        public bool IsReusable
        {
            get { return false; }
        }
    }
}

