/**
 * Dashboard Sĩ số lớp
 * Load: Stored Procedure -> StudentClassSizeDashboardApi.ashx -> ApexCharts
 */
(function () {
    "use strict";

    var API_URL = "/StudentClassSizeDashboardApi.ashx";
    var PRIMARY = "#4b6c9e";
    var SUCCESS = "#2e9e6e";
    var DANGER = "#d9534f";
    var WARNING = "#e8a838";
    var INFO = "#5b9bd5";
    var MUTED = "#adb0bb";

    var chartInstances = {};
    var filterData = null;
    var lastPayload = null;
    var eventsBound = false;

    var baseChartOpts = {
        fontFamily: "inherit",
        foreColor: MUTED,
        toolbar: { show: false },
        width: "100%"
    };

    function formatNumber(val) {
        var num = parseInt(val, 10);
        if (isNaN(num)) {
            return "0";
        }
        return num.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ".");
    }

    function getEl(id) {
        return document.getElementById(id);
    }

    function showState(state) {
        var loading = getEl("scsDashStateLoading");
        var error = getEl("scsDashStateError");
        var empty = getEl("scsDashStateEmpty");
        var content = getEl("scsDashContent");

        if (loading) {
            loading.className = state === "loading" ? "scs-dash-state" : "scs-dash-state d-none";
        }
        if (error) {
            error.className = state === "error" ? "scs-dash-state" : "scs-dash-state d-none";
        }
        if (empty) {
            empty.className = state === "empty" ? "scs-dash-state" : "scs-dash-state d-none";
        }
        if (content) {
            content.style.display = (state === "ready" || state === "empty") ? "" : "none";
        }
    }

    function setErrorMessage(message) {
        var el = getEl("scsDashErrorMessage");
        if (el) {
            el.textContent = message || "Có lỗi xảy ra.";
        }
    }

    function postJson(payload, callback) {
        var xhr = new XMLHttpRequest();
        xhr.open("POST", API_URL, true);
        xhr.setRequestHeader("Content-Type", "application/json; charset=utf-8");
        xhr.onreadystatechange = function () {
            if (xhr.readyState !== 4) {
                return;
            }
            var response = null;
            try {
                response = JSON.parse(xhr.responseText);
            } catch (e) {
                callback(false, "Phản hồi không hợp lệ từ máy chủ.", null);
                return;
            }
            if (!response || !response.success) {
                callback(false, response && response.message ? response.message : "Không tải được dữ liệu.", null);
                return;
            }
            callback(true, "", response.data);
        };
        xhr.send(JSON.stringify(payload));
    }

    function fillSelect(selectId, items, selectedValue, placeholder) {
        var select = getEl(selectId);
        var html = "";
        var i;

        if (!select) {
            return;
        }

        if (placeholder) {
            html += "<option value=\"\">" + placeholder + "</option>";
        }

        for (i = 0; i < items.length; i++) {
            html += "<option value=\"" + items[i].value + "\">" + items[i].text + "</option>";
        }

        select.innerHTML = html;
        if (selectedValue !== null && selectedValue !== undefined && selectedValue !== "") {
            select.value = selectedValue;
        }
    }

    function getCurrentMonthValue() {
        var now = new Date();
        var month = now.getMonth() + 1;
        return now.getFullYear() + "-" + (month < 10 ? "0" + month : month);
    }

    function getFiltersFromDom() {
        return {
            yearId: getEl("scsDashFilterYear") ? getEl("scsDashFilterYear").value : "",
            semester: getEl("scsDashFilterSemester") ? getEl("scsDashFilterSemester").value : "",
            month: getEl("scsDashFilterMonth") ? getEl("scsDashFilterMonth").value : getCurrentMonthValue(),
            scienceId: getEl("scsDashFilterScience") ? getEl("scsDashFilterScience").value : "",
            courseId: getEl("scsDashFilterCourse") ? getEl("scsDashFilterCourse").value : "",
            classId: getEl("scsDashFilterClass") ? getEl("scsDashFilterClass").value : ""
        };
    }

    function bindFilterOptions(data) {
        filterData = data;
        var defaults = data.defaults || {};

        fillSelect("scsDashFilterYear", data.years || [], defaults.YearID, "--Chọn năm học--");
        fillSelect("scsDashFilterSemester", data.semesters || [], defaults.Semester, null);
        fillSelect("scsDashFilterMonth", data.months || [], getCurrentMonthValue(), null);
        fillSelect("scsDashFilterScience", data.sciences || [], "", null);
        fillSelect("scsDashFilterCourse", data.courses || [], "", null);
        fillSelect("scsDashFilterClass", data.classes || [], "", null);
    }

    function loadFilters(callback) {
        postJson({ action: "filters" }, function (success, message, data) {
            if (!success) {
                callback(false, message);
                return;
            }
            bindFilterOptions(data);
            callback(true, "");
        });
    }

    function loadDashboardData(callback) {
        var filters = getFiltersFromDom();
        if (!filters.yearId || !filters.semester) {
            callback(false, "Vui lòng chọn năm học và học kỳ.");
            return;
        }

        lastPayload = filters;
        postJson({
            action: "data",
            yearId: filters.yearId,
            semester: filters.semester,
            month: filters.month,
            scienceId: filters.scienceId,
            courseId: filters.courseId,
            classId: filters.classId
        }, callback);
    }

    function destroyChart(id) {
        if (chartInstances[id]) {
            chartInstances[id].destroy();
            chartInstances[id] = null;
        }
    }

    function renderChart(id, options, emptyId) {
        var el = document.querySelector(id);
        var emptyEl = emptyId ? getEl(emptyId) : null;

        if (!el || typeof ApexCharts === "undefined") {
            return;
        }

        destroyChart(id);

        if (!options || options.isEmpty) {
            el.innerHTML = "";
            if (emptyEl) {
                emptyEl.className = "scs-dash-chart-empty";
            }
            return;
        }

        if (emptyEl) {
            emptyEl.className = "scs-dash-chart-empty d-none";
        }

        chartInstances[id] = new ApexCharts(el, options);
        chartInstances[id].render();
    }

    function toggleChartEmpty(chartId, emptyId, isEmpty) {
        var chartEl = document.querySelector(chartId);
        if (chartEl) {
            chartEl.style.display = isEmpty ? "none" : "";
        }
        if (emptyId) {
            var emptyEl = getEl(emptyId);
            if (emptyEl) {
                emptyEl.className = isEmpty ? "scs-dash-chart-empty" : "scs-dash-chart-empty d-none";
            }
        }
    }

    function updateKpiCards(summaryRows) {
        var summary = (summaryRows && summaryRows.length > 0) ? summaryRows[0] : {};
        var map = {
            "scs-kpi-classes": summary.TotalClass,
            "scs-kpi-students": summary.TotalStudent,
            "scs-kpi-studying": summary.StudyingStudent,
            "scs-kpi-warning": summary.WarningStudent
        };
        var key;

        for (key in map) {
            if (!map.hasOwnProperty(key)) {
                continue;
            }
            var card = getEl(key);
            if (!card) {
                continue;
            }
            var valueEl = card.querySelector(".sch-dash-kpi-value");
            if (valueEl) {
                valueEl.textContent = formatNumber(map[key]);
            }
        }
    }

    function renderByClassChart(targetId, rows, emptyId) {
        var labels = [];
        var series = [];
        var i;

        for (i = 0; i < rows.length; i++) {
            labels.push(rows[i].ClassName);
            series.push(rows[i].StudentCount || 0);
        }

        if (labels.length === 0) {
            destroyChart(targetId);
            toggleChartEmpty(targetId, emptyId, true);
            return;
        }

        toggleChartEmpty(targetId, emptyId, false);
        renderChart(targetId, {
            series: [{ name: "Sĩ số", data: series }],
            chart: Object.assign({ height: 320, type: "bar" }, baseChartOpts),
            plotOptions: {
                bar: {
                    borderRadius: 6,
                    columnWidth: "55%"
                }
            },
            colors: [PRIMARY],
            dataLabels: { enabled: false },
            xaxis: {
                categories: labels,
                labels: {
                    rotate: -45,
                    trim: true,
                    maxHeight: 80
                }
            },
            yaxis: {
                title: { text: "Sinh viên" }
            },
            grid: { strokeDashArray: 4 }
        });
    }

    function renderGenderChart(rows) {
        var labels = [];
        var maleSeries = [];
        var femaleSeries = [];
        var i;

        for (i = 0; i < rows.length; i++) {
            labels.push(rows[i].ClassName);
            maleSeries.push(rows[i].MaleQuantity || 0);
            femaleSeries.push(rows[i].FemaleQuantity || 0);
        }

        if (labels.length === 0) {
            destroyChart("#scsDashChartGender");
            toggleChartEmpty("#scsDashChartGender", "scsDashChartGenderEmpty", true);
            return;
        }

