    /// <summary>
    /// API JSON cho dashboard sĩ số lớp — chỉ action=data.
    /// Bộ lọc bind server-side qua UYearSemesterFilter + UClassFilter.
    /// </summary>
    public class StudentClassSizeDashboardApi : IHttpHandler, IReadOnlySessionState
    {
        private const string PERMISSION_VIEW = "frmWebStudentList_View";
        private const string SP_NAME = "DASH_StudentClassSize_GetData";

        public void ProcessRequest(HttpContext context)
        {
            context.Response.ContentType = "application/json";
            context.Response.ContentEncoding = Encoding.UTF8;

            if (WebGlobal.User == null)
            {
                WriteJson(context, false, "Bạn chưa đăng nhập hệ thống.", null);
                return;
            }

            if (!WebGlobal.HasPermission(PERMISSION_VIEW))
            {
                WriteJson(context, false, "Bạn không có quyền xem dashboard sĩ số lớp.", null);
                return;
            }

            try
            {
                HandleData(context);
            }
            catch (Exception)
            {
                WriteJson(context, false, "Có lỗi xảy ra khi tải dữ liệu dashboard.", null);
            }
        }

        private void HandleData(HttpContext context)
        {
            string strYearId = GetRequestValue(context, "yearId");
            string strSemester = GetRequestValue(context, "semester");
            string strMonth = GetRequestValue(context, "month");
            string strScienceId = GetRequestValue(context, "scienceId");
            string strCourseId = GetRequestValue(context, "courseId");
            string strClassId = GetRequestValue(context, "classId");

            if (strYearId == null || strYearId == "" || strSemester == null || strSemester == "" || strSemester == "-1")
            {
                WriteJson(context, false, "Vui lòng chọn năm học và học kỳ.", null);
                return;
            }

            int intYearId = Convert.ToInt32(strYearId);
            byte bySemester = Convert.ToByte(strSemester);
            DateTime dtmMonth = ParseMonth(strMonth);

            Dictionary<string, DataTable> dicTables = GetDashboardData(
                strScienceId,
                strCourseId,
                strClassId,
                intYearId,
                bySemester,
                dtmMonth);

            if (dicTables["summary"] == null)
            {
                WriteJson(context, false, "Không tải được dữ liệu từ hệ thống.", null);
                return;
            }

            Dictionary<string, object> dicData = new Dictionary<string, object>();
            dicData["summary"] = DataTableToList(dicTables["summary"]);
            dicData["byClass"] = DataTableToList(dicTables["byClass"]);
            dicData["genderByClass"] = DataTableToList(dicTables["genderByClass"]);
            dicData["monthTrend"] = DataTableToList(dicTables["monthTrend"]);
            dicData["byScience"] = DataTableToList(dicTables["byScience"]);
            dicData["abnormal"] = DataTableToList(dicTables["abnormal"]);
            dicData["updatedAt"] = DateTime.Now.ToString("dd/MM/yyyy HH:mm");

            WriteJson(context, true, "", dicData);
        }

        private Dictionary<string, DataTable> GetDashboardData(
            string scienceId,
            string courseId,
            string classId,
            int yearId,
            byte semester,
            DateTime month)
        {
            Dictionary<string, DataTable> dicResult = new Dictionary<string, DataTable>();
            SIM_Class objClass = new SIM_Class();
            object objMonth = month;

            dicResult["summary"] = CallResultSet(objClass, scienceId, courseId, classId, yearId, semester, objMonth, 1);
            dicResult["byClass"] = CallResultSet(objClass, scienceId, courseId, classId, yearId, semester, objMonth, 2);
            dicResult["genderByClass"] = CallResultSet(objClass, scienceId, courseId, classId, yearId, semester, objMonth, 3);
            dicResult["monthTrend"] = CallResultSet(objClass, scienceId, courseId, classId, yearId, semester, objMonth, 4);
            dicResult["byScience"] = CallResultSet(objClass, scienceId, courseId, classId, yearId, semester, objMonth, 5);
            dicResult["abnormal"] = CallResultSet(objClass, scienceId, courseId, classId, yearId, semester, objMonth, 6);

            return dicResult;
        }

        private DataTable CallResultSet(
            SIM_Class objClass,
            string scienceId,
            string courseId,
            string classId,
            int yearId,
            byte semester,
            object month,
            byte resultSet)
        {
            return objClass.GetDataTable(
                SP_NAME,
                "@ScienceID", NormalizeFilter(scienceId),
                "@CourseID", NormalizeFilter(courseId),
                "@ClassID", NormalizeFilter(classId),
                "@YearID", yearId,
                "@Semester", semester,
                "@Month", month,
                "@ResultSet", resultSet);
        }

        private object NormalizeFilter(string value)
        {
            if (value == null || value.Trim() == "" || value == "0" || value.ToLower() == "all")
                return DBNull.Value;
            return value.Trim();
        }

        private List<Dictionary<string, object>> DataTableToList(DataTable dtb)
        {
            List<Dictionary<string, object>> lstRows = new List<Dictionary<string, object>>();
            if (dtb == null)
                return lstRows;

            int intCol;
            int intRow;
            for (intRow = 0; intRow < dtb.Rows.Count; intRow++)
            {
                Dictionary<string, object> dicRow = new Dictionary<string, object>();
                for (intCol = 0; intCol < dtb.Columns.Count; intCol++)
                {
                    object objValue = dtb.Rows[intRow][intCol];
                    if (objValue == DBNull.Value)
                        dicRow[dtb.Columns[intCol].ColumnName] = null;
                    else if (objValue is DateTime)
                        dicRow[dtb.Columns[intCol].ColumnName] = ((DateTime)objValue).ToString("yyyy-MM-dd");
                    else
                        dicRow[dtb.Columns[intCol].ColumnName] = objValue;
                }
                lstRows.Add(dicRow);
            }
            return lstRows;
        }

        private DateTime ParseMonth(string strMonth)
        {
            if (strMonth == null || strMonth == "")
                return Convert.ToDateTime(DateTime.Now.ToString("yyyy-MM-01"));

            if (strMonth.Length == 7)
                return Convert.ToDateTime(strMonth + "-01");

            return Convert.ToDateTime(strMonth);
        }

        private string GetRequestValue(HttpContext context, string key)
        {
            if (context.Request[key] != null && context.Request[key] != "")
                return context.Request[key];

            string strBody = ReadRequestBody(context);
            if (strBody == null || strBody == "")
                return null;

            JavaScriptSerializer objSerializer = new JavaScriptSerializer();
            Dictionary<string, object> dicBody = objSerializer.Deserialize<Dictionary<string, object>>(strBody);
            if (dicBody == null || !dicBody.ContainsKey(key) || dicBody[key] == null)
                return null;

            return Convert.ToString(dicBody[key]);
        }

        private string ReadRequestBody(HttpContext context)
        {
            if (context.Request.InputStream == null)
                return null;

            context.Request.InputStream.Position = 0;
            StreamReader objReader = new StreamReader(context.Request.InputStream, Encoding.UTF8);
            return objReader.ReadToEnd();
        }

        private void WriteJson(HttpContext context, bool success, string message, object data)
        {
            Dictionary<string, object> dicResponse = new Dictionary<string, object>();
            dicResponse["success"] = success;
            dicResponse["message"] = message;
            dicResponse["data"] = data;

            JavaScriptSerializer objSerializer = new JavaScriptSerializer();
            objSerializer.MaxJsonLength = int.MaxValue;
            context.Response.Write(objSerializer.Serialize(dicResponse));
        }

        public bool IsReusable
        {
            get { return false; }
        }
    }
}

