        return;
    }

    if (placeholder) {
        html += "<option value=\"\">" + placeholder + "</option>";
    }

    for (i = 0; i < items.length; i++) {
        html += "<option value=\"" + items[i].value + "\">" + items[i].text + "</option>";
    }

    select.innerHTML = html;
    if (selectedValue !== null && selectedValue !== undefined && selectedValue !== "") {
        select.value = selectedValue;
    }
}

function getCurrentMonthValue() {
    var now = new Date();
    var month = now.getMonth() + 1;
    return now.getFullYear() + "-" + (month < 10 ? "0" + month : month);
}

function getFiltersFromDom() {
    return {
        yearId: getEl("scsDashFilterYear") ? getEl("scsDashFilterYear").value : "",
        semester: getEl("scsDashFilterSemester") ? getEl("scsDashFilterSemester").value : "",
        month: getEl("scsDashFilterMonth") ? getEl("scsDashFilterMonth").value : getCurrentMonthValue(),
        scienceId: getEl("scsDashFilterScience") ? getEl("scsDashFilterScience").value : "",
        courseId: getEl("scsDashFilterCourse") ? getEl("scsDashFilterCourse").value : "",
        classId: getEl("scsDashFilterClass") ? getEl("scsDashFilterClass").value : ""
    };
}

function bindFilterOptions(data) {
    filterData = data;
    var defaults = data.defaults || {};

    fillSelect("scsDashFilterYear", data.years || [], defaults.YearID, "--Chọn năm học--");
    fillSelect("scsDashFilterSemester", data.semesters || [], defaults.Semester, null);
    fillSelect("scsDashFilterMonth", data.months || [], getCurrentMonthValue(), null);
    fillSelect("scsDashFilterScience", data.sciences || [], "", null);
    fillSelect("scsDashFilterCourse", data.courses || [], "", null);
    fillSelect("scsDashFilterClass", data.classes || [], "", null);
}

function loadFilters(callback) {
    postJson({ action: "filters" }, function (success, message, data) {
        if (!success) {
            callback(false, message);
            return;
        }
        bindFilterOptions(data);
        callback(true, "");
    });
}

function loadDashboardData(callback) {

if (btnRefresh) {
